  let mut input = String::new();
  io::stdin().read_to_string(&mut input).unwrap();
  let lines: Vec<String> = input.split('\n').map(|l| l.trim_end_matches('\r').to_string()).collect();
  let mut idx: usize = 0;
  let mut next_line = || -> String {
    if idx < lines.len() { let s = lines[idx].clone(); idx += 1; s } else { String::new() }
  };

    let height_n: usize = next_line().trim().parse().unwrap_or(0);
    let height: Vec<i32> = if height_n > 0 { next_line().trim().split_whitespace().map(|x| x.parse().unwrap_or(0)).collect() } else { Vec::new() };
  let result = solve(height);
  println!("{}", result);
}

